<?php
declare(strict_types=1);
return static function(PDO $pdo):void{$key=hash('sha256',(string)(getenv('APP_KEY')?:'arete-managed-credentials'),true);foreach(['student_accounts','employee_accounts']as$table){$rows=$pdo->query("SELECT user_id FROM {$table} WHERE password_cipher IS NULL OR password_cipher='' ")->fetchAll(PDO::FETCH_COLUMN);$updateUser=$pdo->prepare('UPDATE users SET password_hash=:hash,updated_at=:updated WHERE id=:id');$updateLink=$pdo->prepare("UPDATE {$table} SET password_cipher=:cipher,updated_at=:updated WHERE user_id=:id");foreach($rows as$userId){$plain='Arete-'.strtoupper(substr(bin2hex(random_bytes(6)),0,10));$iv=random_bytes(12);$tag='';$encrypted=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);if($encrypted===false)throw new RuntimeException('Credential encryption failed.');$now=date('Y-m-d H:i:s');$updateUser->execute(['hash'=>password_hash($plain,PASSWORD_DEFAULT),'updated'=>$now,'id'=>$userId]);$updateLink->execute(['cipher'=>base64_encode($iv.$tag.$encrypted),'updated'=>$now,'id'=>$userId]);}}};
